{
  "terraform": {
    "required_version": ">= 1.5.0",
    "required_providers": {
      "aws": {
        "source": "hashicorp/aws"
      },
      "azurerm": {
        "source": "hashicorp/azurerm"
      },
      "google": {
        "source": "hashicorp/google"
      }
    }
  },
  "variable": {
    "azure_subscription": {
      "type": "string"
    },
    "gcp_project": {
      "type": "string"
    },
    "orders_bucket": {
      "type": "string"
    },
    "azure_storage_name": {
      "type": "string"
    },
    "factory_name": {
      "type": "string"
    },
    "curated_bucket": {
      "type": "string"
    }
  },
  "provider": {
    "aws": {
      "region": "ap-northeast-2"
    },
    "azurerm": {
      "features": [
        {}
      ],
      "subscription_id": "${var.azure_subscription}"
    },
    "google": {
      "project": "${var.gcp_project}",
      "region": "asia-northeast3"
    }
  },
  "resource": {
    "aws_s3_bucket": {
      "orders": {
        "bucket": "${var.orders_bucket}"
      }
    },
    "aws_s3_bucket_versioning": {
      "orders": {
        "bucket": "${aws_s3_bucket.orders.id}",
        "versioning_configuration": [
          {
            "status": "Enabled"
          }
        ]
      }
    },
    "aws_s3_bucket_public_access_block": {
      "orders": {
        "bucket": "${aws_s3_bucket.orders.id}",
        "block_public_acls": true,
        "block_public_policy": true,
        "ignore_public_acls": true,
        "restrict_public_buckets": true
      }
    },
    "azurerm_resource_group": {
      "reporting": {
        "name": "rg-retail-reporting",
        "location": "koreacentral"
      }
    },
    "azurerm_storage_account": {
      "regional": {
        "name": "${var.azure_storage_name}",
        "account_tier": "Standard",
        "account_replication_type": "ZRS",
        "account_kind": "StorageV2",
        "is_hns_enabled": true,
        "resource_group_name": "${azurerm_resource_group.reporting.name}",
        "location": "${azurerm_resource_group.reporting.location}"
      }
    },
    "azurerm_storage_data_lake_gen2_filesystem": {
      "published": {
        "name": "published",
        "storage_account_id": "${azurerm_storage_account.regional.id}"
      }
    },
    "azurerm_data_factory": {
      "reporting": {
        "name": "${var.factory_name}",
        "identity": [
          {
            "type": "SystemAssigned"
          }
        ],
        "resource_group_name": "${azurerm_resource_group.reporting.name}",
        "location": "${azurerm_resource_group.reporting.location}"
      }
    },
    "google_storage_bucket": {
      "curated": {
        "name": "${var.curated_bucket}",
        "location": "ASIA-NORTHEAST3",
        "uniform_bucket_level_access": true,
        "public_access_prevention": "enforced"
      }
    },
    "google_bigquery_dataset": {
      "retail": {
        "dataset_id": "retail",
        "location": "asia-northeast3"
      }
    },
    "google_bigquery_table": {
      "orders": {
        "dataset_id": "${google_bigquery_dataset.retail.dataset_id}",
        "table_id": "orders",
        "external_data_configuration": [
          {
            "autodetect": true,
            "source_format": "PARQUET",
            "source_uris": [
              "gs://${google_storage_bucket.curated.name}/orders/*.parquet"
            ]
          }
        ]
      }
    },
    "google_vertex_ai_dataset": {
      "forecast": {
        "display_name": "demand-forecast",
        "metadata_schema_uri": "gs://google-cloud-aiplatform/schema/dataset/metadata/tabular_1.0.0.yaml",
        "region": "asia-northeast3"
      }
    }
  }
}
